def _fit(xs, ys):
    """OLS through the swing points -- Wyckoff's creek is a sloping line."""
    k = len(xs)
    mx = sum(xs) / k
    my = sum(ys) / k
    sxx = 0.0
    sxy = 0.0
    for a in range(k):
        dx = xs[a] - mx
        sxx += dx * dx
        sxy += dx * (ys[a] - my)
    if sxx <= 0.0:
        return 0.0, my
    m = sxy / sxx
    return m, my - m * mx


def family_init(ctx):
    b = ctx.bars
    n = len(b)
    h = [float(x["h"]) for x in b]
    l = [float(x["l"]) for x in b]
    c = [float(x["c"]) for x in b]
    v = [float(x.get("v") or 0.0) for x in b]

    an = int(ctx.p.atr_n)
    fr = int(ctx.p.fractal)
    npts = int(ctx.p.n_points)
    win = int(ctx.p.win)
    rngm = float(ctx.p.rng_mult)
    jsp = float(ctx.p.jump_spread)
    jvol = float(ctx.p.jump_vol)
    jloc = float(ctx.p.jump_loc)
    bprox = float(ctx.p.bu_prox)
    bvol = float(ctx.p.bu_vol)
    brng = float(ctx.p.bu_range)
    blo = int(ctx.p.bu_lo)
    bhi = int(ctx.p.bu_hi)
    ewin = int(ctx.p.entry_win)
    abrt = float(ctx.p.abort_mult)
    vn = int(ctx.p.vol_n)

    atr = [None] * n
    acc = 0.0
    prev = None
    for j in range(n):
        if j == 0:
            tr = h[0] - l[0]
        else:
            pc = c[j - 1]
            tr = max(h[j] - l[j], abs(h[j] - pc), abs(l[j] - pc))
        if j < an:
            acc += tr
            if j == an - 1:
                prev = acc / an
                atr[j] = prev
        else:
            prev = ((an - 1) * prev + tr) / an
            atr[j] = prev

    av = [None] * n
    run = 0.0
    for j in range(n):
        run += v[j]
        if j >= vn:
            run -= v[j - vn]
        if j >= vn - 1:
            av[j] = run / vn

    # 7-bar fractal swings; a swing at j is only KNOWN at bar j+fr
    sh = []
    sl = []
    for j in range(fr, n - fr):
        hh = h[j]
        ll = l[j]
        up = True
        dn = True
        for k in range(1, fr + 1):
            if up and not (hh > h[j - k] and hh > h[j + k]):
                up = False
            if dn and not (ll < l[j - k] and ll < l[j + k]):
                dn = False
            if not up and not dn:
                break
        if up:
            sh.append(j)
        if dn:
            sl.append(j)

    cnt_h = [0] * n
    cnt_l = [0] * n
    a_ = 0
    b_ = 0
    for i in range(n):
        while a_ < len(sh) and sh[a_] <= i - fr:
            a_ += 1
        cnt_h[i] = a_
        while b_ < len(sl) and sl[b_] <= i - fr:
            b_ += 1
        cnt_l[i] = b_

    def creek(i, want_high):
        pts = sh if want_high else sl
        cnt = cnt_h[i] if want_high else cnt_l[i]
        if cnt < npts:
            return None
        sel = pts[cnt - npts:cnt]
        if sel[0] < i - win:
            return None
        src = h if want_high else l
        return _fit(sel, [src[j] for j in sel])

    hi_run = [None] * n
    lo_run = [None] * n
    for j in range(win - 1, n):
        hi_run[j] = max(h[j - win + 1:j + 1])
        lo_run[j] = min(l[j - win + 1:j + 1])

    sig = [0] * n
    creekv = [None] * n
    J = max(an, win, vn, fr + 1)
    while J < n:
        a = atr[J]
        if a is None or a <= 0 or not av[J] or hi_run[J] is None:
            J += 1
            continue
        # containment: this must still look like a trading range, not a trend
        if (hi_run[J] - lo_run[J]) > rngm * a:
            J += 1
            continue
        rng = h[J] - l[J]
        if rng <= 0:
            J += 1
            continue
        loc = (c[J] - l[J]) / rng
        got = None
        for d in (1, -1):
            fit = creek(J, d > 0)
            if fit is None:
                continue
            m, q = fit
            if (d > 0 and m > 0.0) or (d < 0 and m < 0.0):
                continue
            cj = m * J + q
            ok = rng >= jsp * a and v[J] >= jvol * av[J]
            if d > 0:
                ok = ok and c[J] > cj + 0.10 * a and loc >= jloc
            else:
                ok = ok and c[J] < cj - 0.10 * a and loc <= 1.0 - jloc
            if ok:
                got = (d, m, q)
                break
        if got is None:
            J += 1
            continue
        d, m, q = got
        B = None
        E = None
        t = J + 1
        limit = min(n, J + 1 + bhi)
        while t < limit:
            ct = m * t + q
            at = atr[t] or a
            if (d > 0 and c[t] < ct - abrt * at) or (d < 0 and c[t] > ct + abrt * at):
                break
            if B is None:
                if t >= J + blo:
                    rt = h[t] - l[t]
                    if av[t] and v[t] <= bvol * av[t] and rt <= brng * at:
                        if d > 0 and l[t] <= ct + bprox * at and c[t] > ct:
                            B = t
                        elif d < 0 and h[t] >= ct - bprox * at and c[t] < ct:
                            B = t
                    if B is not None:
                        lim2 = min(n, B + 1 + ewin)
                        if lim2 > limit:
                            limit = lim2
            else:
                if d > 0 and c[t] > h[B]:
                    E = t
                    break
                if d < 0 and c[t] < l[B]:
                    E = t
                    break
            t += 1
        if E is not None:
            sig[E] = d
            for u in range(E, min(n, E + 120)):
                creekv[u] = m * u + q
            J = E + 1
        elif B is not None:
            J = B + 1
        else:
            J += 1

    ctx.sig = ctx.series(sig, "creek_entry")
    ctx.creek = ctx.series(creekv, "creek_line")
    ctx.catr = ctx.series(atr, "creek_atr")


def signal(ctx, i):
    s = ctx.sig[i]
    return 0 if s is None else int(s)


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    cv = ctx.creek[i]
    a = ctx.catr[i]
    if cv is None or a is None:
        return False
    k = float(ctx.p.abort_mult)
    if ctx.positions[0]["side"] == "long":
        return ctx.c[i] < cv - k * a
    return ctx.c[i] > cv + k * a
